//! Standalone asset desktop/headless development consumers with explicit selected providers; no
//! unconditional all-domain facade, no separately shipped suite app.
//!
//! The default build is headless and window-free: the library drives the real session (open,
//! revision-checked provider submit, atomic save, reopen) and the controls descriptors; the
//! `studio-harness` example is a thin forwarder to [`cli::run`]. Feature `viewer` adds the desktop
//! viewer state and egui UI ([`view`], still window-free and headless-testable); feature `desktop`
//! adds the eframe window host, binary `studio-harness` (Operator decision D11: eframe 0.33.3 with
//! its wgpu backend, only in this crate). Launching the window is a manual Operator step
//! (`RUN-UI.md`).
#![forbid(unsafe_code)]

pub mod cli;
mod harness;
pub mod import;
pub mod manual;
pub mod panel;
#[cfg(feature = "viewer")]
pub mod view;

pub use harness::{
    AVAILABLE_PROVIDERS, Harness, HarnessError, NOT_PROVEN, Place, PlacementWrite, References, Run, SCHEMA, Selection, default_actor,
};

